// Run first: returns the 10 nearest documents with id, title and distance, in rank order.
query nearest_docs($q: Vector(3)) {
    match { $d: Doc }
    return { $d.id, $d.title, nearest($d.embedding, $q) as distance }
    order { nearest($d.embedding, $q) }
    limit 10
}
```

```gq
// Run second: pass the ids from the first result as $ids. Merge by id into the first result as `cites`. Any id absent from this result cites nothing, so the caller sets its `cites` to 0.
query cite_counts($ids: [String]) {
    match {
        $d: Doc
        $d.id in $ids
        $d cites $c
    }
    return { $d.id, count($c) as cites }
}
